const CZ = 128, RA = 124, RB = 132;

const ball = (cx, cy, cz, r, t) => {
  for (let dx = -r; dx <= r; dx++) for (let dy = -r; dy <= r; dy++) for (let dz = -r; dz <= r; dz++)
    if (dx * dx + dy * dy + dz * dz <= r * r) block(cx + dx, cy + dy, cz + dz, t);
};
const xDisc = (x, cy, cz, r2, t) => {
  const r = Math.ceil(Math.sqrt(r2));
  for (let dy = -r; dy <= r; dy++) for (let dz = -r; dz <= r; dz++)
    if (dy * dy + dz * dz <= r2) block(x, cy + dy, cz + dz, t);
};
const vCyl = (cx, cz, y0, y1, r2, t) => {
  const r = Math.ceil(Math.sqrt(r2));
  for (let y = y0; y <= y1; y++) for (let dx = -r; dx <= r; dx++) for (let dz = -r; dz <= r; dz++)
    if (dx * dx + dz * dz <= r2) block(cx + dx, y, cz + dz, t);
};
const wheel = (x, zc) => {
  xDisc(x, 7, zc, 9, "black_wool");
  xDisc(x + 1, 7, zc, 9, "black_wool");
  block(x, 7, zc, "gold_block");
  block(x + 1, 7, zc, "gold_block");
};
const tree = (tx, tz) => {
  const h = 4 + Math.floor(rng() * 3), r = 3 + Math.floor(rng() * 2);
  box(tx, 2, tz, tx, 1 + h, tz, "oak_log");
  for (let dx = -r; dx <= r; dx++) for (let dy = -r + 1; dy <= r; dy++) for (let dz = -r; dz <= r; dz++)
    if (dx * dx + dy * dy + dz * dz <= r * r + rng() * 2 - 1) block(tx + dx, 1 + h + dy, tz + dz, "oak_leaves");
};
