const car = (a, b) => {
  box(a, 9, 122, b, 9, 134, "iron_block");
  box(a, 10, 123, b, 17, 133, "red_wool");
  for (let dz = -6; dz <= 6; dz++) box(a, 18, CZ + dz, b, 18 + Math.floor(Math.sqrt(42.25 - dz * dz)), CZ + dz, "gray_wool");
  box(a, 11, 122, b, 11, 122, "gold_block");
  box(a, 11, 134, b, 11, 134, "gold_block");
  for (let x = a + 1; x <= b - 1; x++) {
    if ((x - a) % 4 === 0) {
      box(x, 10, 122, x, 17, 122, "red_wool");
      box(x, 10, 134, x, 17, 134, "red_wool");
    } else {
      box(x, 12, 123, x, 16, 123, "glass");
      box(x, 12, 133, x, 16, 133, "glass");
    }
  }
  wheel(a + 2, RA); wheel(a + 2, RB);
  wheel(b - 3, RA); wheel(b - 3, RB);
};

